#include <utility>
#include <iostream>

class Point {
    int x_, y_;
public:
    Point(int x, int y) : x_(x), y_(y) {}
    bool operator==(const Point& other) const { return x_ == other.x_ && y_ == other.y_; }
    bool operator<(const Point& other) const { return x_ < other.x_; }
};

void compare_points(const Point& p1, const Point& p2) {
    using namespace std::rel_ops; // Enable automatic operators

    // Uses Point::operator==
    if (p1 != p2) {
        std::cout << "Points are not equal.\n";
    }

    // Uses Point::operator< (p2 < p1)
    if (p1 > p2) {
        std::cout << "P1 is greater than P2 (by X coordinate).\n";
    }
}
